import type { Story } from "./stories";

export const stories2000: Record<number, Story> = {
	2000: {
		index: 2000,
		text: `<p>You see an old man and a young boy arguing animatedly over "the fools' gold." Intrigued, you eavesdrop and discover they are stealing from visitors. The old man distracts the mark by asking for aid, while the young boy slits their pouch. You shadow the pair for the entire day while you formulate a plan.</p>
<p><b>No Skill:</b> Mid-way through the day, the boy notices you. The two thieves lead you into an ambush, where you are knocked senseless. [D1/<em>Wounded</em>]</p>
<p><b>Stealth and Stealing:</b> The pair beds down in a ruined area, far from the crowds. During the night, you help yourself to their ill-gotten gains. You discover a most valuable item among their petty earnings. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2001: {
		index: 2001,
		text: `<p>A hirsute man loudly hawks his miraculous hair-growth ointment to all passers-by of bald pate. Curious, you approach and ask about the ointment's ingredients. The man claims it is an ancient family recipe, responsible for his full head of lush hair, and will not describe it further. You suspect a deception.</p>
<p><b>No Skill:</b> You continue to pester the man with questions until he tires of your antics and packs up his vials. [D1/<em>Determined</em>]</p>
<p><b>Scholarship:</b> Your erudite inquiries show the man that you are knowledgeable about the various properties of herbs and concoctions. During your disquisition, a crowd gathers. His inability to answer even simple queries about the subject convince the audience that he is a fraudster. Impressed, the gathering showers you with praise. One comely member, checks aglow with rapture, seeks your company. [D2/S1/<b>Beloved</b>]</p>`,
	},
	2002: {
		index: 2002,
		text: `<p>As you rest from the rigors of travel, a richly dressed prince and his entourage pass by. Noting the dust on your clothes, he knows you to be a traveler. He draws a weathered map from an ivory tube, explaining that he recently purchased this from an honest-seeming barker, but now he wonders if he was duped. He wishes to know if you can authenticate the map. You ask him a handful of questions about its provenance and then study it for several minutes.</p>
<p><b>No Skill:</b> Convinced that it is a fake, you lamely attempt to point out deficiencies in the map, but are unable to make your case. The prince and his cohort soon quit themselves of you. [S1/<em>Envious</em>]</p>
<p><b>Wilderness Lore:</b> At least a portion of the map relates to areas you have visited. Other sections cannot be true given what you know about the natural world. Your explanation of the flaws is reasoned and complete, yet you convey your doubts with suitable discretion to avoid embarrassment on the part of the prince. He rewards you with a bauble he had been carrying, and the map itself which holds some worthwhile information. [D2/S1/Wilderness Lore/<b>Treasure</b>]</p>`,
	},
	2003: {
		index: 2003,
		text: `<p>Having heard rumors of a fabled Jeweled Fortress, you seek more information about the subject. You are directed to an old man perched on a high stool in a room filled with books. Looking up from his tome, he listens to your questions but slowly shakes his head. The information you seek will not come cheaply, and it is difficult for "common" people to understand.</p>
<p><em>You may pay the scholar (as long as your Wealth is Poor or greater) and listen to his ramblings, or you may leave well enough alone.</em></p>
<p><em>If you depart:</em> You hang your head in sorrow as you leave the scholar's home. You notice a trinket lying in the road, covered in mud. Fetching it, you rub vigorously and it turns out to be a plain golden ring. Today has not been completely wasted! [W+1 (Max: Poor)]</p>
<p><em>If you pay:</em> The old man invites you back the next day. Upon your return, he launches into a lengthy and convoluted recital, referencing obscure passages and cryptic legends.</p>
<p><b>No Skill:</b> You are quickly befuddled by the wizened one's exposition, as he intended. Convinced that your denseness is the cause of your puzzlement, you stagger from the house and drown your sorrows in a local tavern. [S1/W-1 (Min: Penniless)/<em>Grief Stricken</em>]</p>
<p><b>Enduring Hardship:</b> The old one takes far too long to get to any particular point, and he speaks quickly and with odd phrasing. You come to understand that he is trying to perplex more than elucidate. Still, there are nuggets of good information among the flotsam he spouts. You stoically follow his presentation, guiding him out of the channels of fraud into true knowledge whenever you can. After a number of hours, you feel you have gotten what you asked for, and far more than the codger intended. [D1/S2/W-1 (Min: Penniless)/Opportunity to enter the Jeweled Fortress]</p>`,
	},
	2004: {
		index: 2004,
		text: `<p>An unpleasant fellow, with two soldiers at his side, approaches you as you travel down a public road. He claims to be a tax collector, and imposes a surcharge for your use of the passage. You notice that the soldier's gear is mismatched and tarnished. Suspecting a scam, you loudly proclaim your faith in Allah, and seek his blessing in easing your way through life. You attract a crowd with your pious entreaties.</p>
<p><b>No Skill:</b> You present a pathetic and embarrassing sight. The crowd is amused. The ringleader raps you sharply on the head with his cudgel, and snatches some of your belongings. [D1/W-1 (Min: Penniless)]</p>
<p><b>Appearance:</b> Your endearing visage and pious manner passionately conveys your plight, and the crowd takes up your call. In the hubbub, the strong men skulk out of sight. [D2/S1/Quick Thinking]</p>`,
	},
	2005: {
		index: 2005,
		text: `<p>A gathering of raucous citizens surrounds a colorfully robed and turbaned man and a crippled old woman. He is performing an elaborate ritual in an attempt to cure her of her afflictions. He has mesmerized the crowd with his words, his gestures, and a heady incense. Further at the back, you are unaffected. You also remember seeing the old wretch earlier that day, walking about on both, apparently very sound, legs. You push forward, calling on Allah to end this sham before anyone is falsely separated from his coins.</p>
<p><b>No Skill:</b> Your interruption breaks the trance spun by the performer. Annoyed, the crowd find your sanctimonious urgings and off-putting manner a poor substitute for the old man's enchanting air. They jeer you until you depart. [S1/<em>Scorned</em>]</p>
<p><b>Magic:</b> You note the foolishness of the would-be magician's rituals, and stomp out the burning incense. You finish with a flashy spell that sends the old woman sprawling, revealing the strap holding her leg under her wraps. The crowd beats both man and woman alike. [D1/S2/Beguiling/<em>Respected</em>]</p>`,
	},
	2006: {
		index: 2006,
		text: `<p>You join a crowd watching a young man as he draws patterned cards from a face-down pile. He becomes increasingly flushed when an oily entertainer guesses the image on the face of that card over and over again. When the young man's coin purse is empty, he accuses the performer of cheating him. The card sharp takes offense and daggers are drawn. You step forward, beseeching the pair to trust in Allah and seek his judgment.</p>
<p><b>No Skill:</b> The two turn on you, resenting your interference. Still, by expending their derision and passion on you, their anger with each other cools and they depart without further incident. [D2]</p>
<p><b>Piety:</b> You deliver a bold and insightful prayer to Allah, weaving in observations about the two men and how greater faith would aid them. The combatants are touched, forget their dispute, and bow down with you. The slick operator reveals the trick behind his perfect guessing, and offers to return the dupe his coins. The fleeced one comes to appreciate the skill behind the scam, and urges the entertainer to keep half the monies. The crowd is uplifted by this resolution. [D2/S2/Luck/<em>Blessed</em>]</p>`,
	},
	2007: {
		index: 2007,
		text: `<p>Someone stokes your fire during the night and disturbs your rest. A well-dressed, apparently cultured gooleh bids you a fine evening. Thinking quickly, you engage the gooleh in conversation, praising her sharp fangs and pale flesh. She calmly describes her malign intentions and seems to take some delight in the horrors she will inflict upon you.</p>
<p><b>No Skill:</b> Your bile rises as panic takes control. Dashing off into the night upon terror-strengthened legs, you escape. The monster's braying laugh echoes in your ears for days. [S2/W-1 (Min: Penniless)/<em>Grief Stricken</em>]</p>
<p><b>Bargaining and Evaluation, Quick Thinking:</b> Despite the provocation, you remain calm. Amused by your self-control, the fiend allows herself to be drawn into an extended discussion. In time, you explain while that you would be honored to be consumed by one so sophisticated, the esteemed gooleh would be better served by visiting a group of much plumper, and no-doubt much more tender infidels who can be found nearby. Thanking you for your pleasantness and recommendation, the monster departs. [D2/S1/Beguiling]</p>`,
	},
	2008: {
		index: 2008,
		text: `<p>A ravenous gooleh, frothing at the mouth, springs from the shadows and moves toward you. Her green-tinged, misshapen arms reach for your throat, and you can smell her rancid breath. You kneel down, casting your sword aside, and offer yourself to her hunger. "If Allah sees fit to take me into His kingdom now so that you may sustain yourself, so be it."</p>
<p><b>No Skill, Weapon Use</b> (mandatory): You cannot bring yourself to stand by and be eaten. You dive for your discarded sword and fight for your life! Your sudden resistance surprises the beast, and she lopes away to find easier prey. [D2]</p>
<p><b>Appearance, Seduction:</b> The fiend's desire is tempered by your willingness to abide by Allah's will. But her hunger cannot be contained. She mercifully knocks you out so you won't feel the pain, and only gnaws on you for a short while before departing. [D2/S2/Piety/Lose Appearance/<em>Wounded</em>]</p>`,
	},
	2009: {
		index: 2009,
		text: `<p>You awaken one night to find a group of horrid goolehs closing in about you. You gaze over their numbers and understand you cannot run from your fate tonight. Rising to your knees, you cast your gaze to the heavens, and exclaim, "Allah, praise be to you! The wonders of your creation are manifest for all to see, and I thank you for granting me such a singular sight!"</p>
<p><b>No Skill:</b> The pack is unimpressed by your words. They fall upon and your shrieks fill the night. After a time, they leave you, barely alive and bleeding heavily. Moments later, a healer appears, drawn by your screams. Over the next several weeks, he nurses you back to health, but he requires a task from you in return. [D2/<em>Under Geas</em>]</p>
<p><b>Piety:</b> The deadly horde is taken aback by the strength of your faith. A few are so moved that they clamor that you be left alone. Others are not so forgiving, and sharp words are exchanged. One monster strikes another, and the pack dissolves into a massive skirmish. When several gooleh fall to claw and fang, the rest consume them in their frenzy. Sated, the survivors skulk off into the night. [D2/S1/Luck/<em>Fated</em>]</p>`,
	},
	2010: {
		index: 2010,
		text: `<p>As you travel one day, you hear a tearing, gnashing sound. You move quietly around some obstacles and spy two gooleh devouring a poor herdsman. In their hunger, the gooleh have dropped their belongings, including a leather satchel. No doubt it was stolen from another victim. You cannot help the youth, but you can exact some retribution.</p>
<p><b>No Skill:</b> As you attempt to snatch the pack, one of the gooleh hears you. The two spring up and bellow at you. You back away fearfully. The gooleh are unwilling to leave their meal so you are able to escape. [S1]</p>
<p><b>Stealth and Stealing:</b> You stealthily remove the satchel from the area, and find a valuable treasure buried at the bottom. When you arrive at a nearby town, you report the shepherd's demise to authorities. [D1/S1/<b>Magic Bead</b>]</p>`,
	},
	2011: {
		index: 2011,
		text: `<p>You are sneaking around the site of a recent battle in a small town between two mighty kingdoms, looking for loot, when you hear a horrid keening from a decrepit building nearby. Moving closer, you see a gooleh and her three children consuming the remains of what appears to be a soldier. The tears in their eyes do not seem to slack their appetites. You circle the house, looking for the guardsman's weapons. You find a heavy spear, on it impaled yet another gool child.</p>
<p><b>No Skill:</b> Revolted by this situation, you grab the spear and rush to the nearest army tent. The guards dispatch the beast and her spawn, claiming all the credit for themselves. [S1]</p>
<p><b>Acting and Disguise:</b> You prop the dead creature up on the weapon, and push it through a crumbled wall. With a guttural wail, you accuse the family of dishonoring "your" memory. Ashamed, the monsters flee. [D1/S1/Quick Thinking]</p>`,
	},
	2012: {
		index: 2012,
		text: `<p>You happen upon a camp of a flesh-eating ogre and ogress. The two are huddled in their ragged cloaks and seem distraught. More curious than fearful, you approach to eavesdrop on their conversation. They bemoan a debilitating hunger that has left them despairing and weak. Sprinting through their camp, you snatch several of their belongings and rush off into the countryside. Your daring enrages the desolate fiends, and they give chase.</p>
<p><b>No Skill:</b> You stay ahead of the beasts, but just barely. After a long and tiring hike, you duck into the next settlement you reach. It is clear that the gool and gooleh know where you are hiding. [D1/<em>Pursued</em>]</p>
<p><b>Wilderness Lore:</b> In the end, your mastery of terrain leaves the beasts thrashing futilely in your wake. You learn a thing or two about evasion and caution during the long chase. [D1/S1/Stealth and Stealing]</p>`,
	},
	2013: {
		index: 2013,
		text: `<p>A beggar offers to show you a wondrous sight for a few coins. You agree and are lead to decrepit building. A moaning figure gently rocks before a small campfire, head in hands. A freshly bloodied corpse lies nearby. You ask what is so wondrous about this grotesquery. The beggar says quietly "Watch." After a moment, the figure pushes back her hood and raises her head to the heavens, revealing the visage of a gooleh, tears streaming down her checks. "I cannot abide by my nature, but what can I do? I must eat," she exclaims to no one. The beggar nudges you and points to the bulging sack at the gooleh's side. Noting her evident fatigue, you creep to the upper reaches of the building and begin playing softly on an oud.</p>
<p><em>Roll two dice, adding one each for Beguiling, Courtly Graces, and Storytelling:</em></p>
<p>❖ 2–7: The gooleh immediately notices you. Displeased by your music, she moves off, taking her bag with her. [S1]</p>
<p>❖ 8+: The tired beast drifts off to sleep, lulled by your soft, hypnotic droning. You push yourself to continue, waiting until she is fully asleep. You make off with her bag without difficulty, finding a valuable item inside. [D1/S2/Enduring Hardship/<b>Treasure</b>]</p>`,
	},
	2014: {
		index: 2014,
		text: `<p>You pause during your travels to aid a stricken beggar. As you pull back her hood to ask what ails her, you discover that she is a gooleh. You swallow your disgust and question her. She tells you she has learned a bit of magic and has used it to allow her to ignore her hunger. She is dying of starvation, but will do nothing about it.</p>
<p><b>No Skill:</b> You understand the monster's motivations and approve. Even so, the magic wears off and she dies in agony. [S1]</p>
<p><b>Storytelling:</b> Taken by the beast's self-sacrifice, you attempt to ease her passage into Allah's graces by recounting some melancholy but engaging tales. Gratified, she teaches you something about magic so that you can recast the spell that keeps her in stupor. She dies at peace. [D1/S1/Magic]</p>`,
	},
	2015: {
		index: 2015,
		text: `<p>With a roar, a salivating gooleh lopes out of the darkness toward you. Holding up your hands, you back away, asking why the monster has picked you to eat, and if there is no way you can convince her to leave you be.</p>
<p><b>No Skill:</b> The gooleh is unimpressed with your attempts at conversation. She takes several bites from your flesh and, sated, moves off. [D1/<em>Wounded</em>]</p>
<p><b>Beguiling, Seduction:</b> The monster pauses, staggered by your presence. You questions lead to conversation and several hours of discussion. You learn much about how she survives in the wild. In the end, her hunger cannot be contained and she prepares to feast on you. By that time, she is weakened, however, and you dispatch her with your sword. [D2/S1/Weapon Use]</p>`,
	},
	2016: {
		index: 2016,
		text: `<p>A family of starving monsters, lead by a powerful gooleh, surrounds your camp. "Although it is against Allah's law, we cannot contain our desires, and you must be sacrificed to sustain us." Noting her air of civilization, you question their intentions and ask for a few moments to present an alternative.</p>
<p><b>No Skill:</b> At her command, the pack listens to your entreaties. Your proposal is met with indifference, but the gooleh appreciates the attempt to address their needs. She halts the group before they consume you entirely. [D1/<em>Crippled</em>]</p>
<p><b>Scholarship:</b> You detail a secluded valley that you've heard about, far from any soldier's patrols. This vale is bountiful in water and animals, including a rare deer whose flesh tastes just like human. You suggest that the family journey to this place and live free from sin and danger. The gooleh is moved and commends your wisdom and knowledge. [D2/S1/Wilderness Lore]</p>`,
	},
	2017: {
		index: 2017,
		text: `<p>A heavily robed beggar staggers against you, his stench offending your nostrils. He clutches at your arm with gray-skinned hands. As you push him away, his hood falls off and you see the horrid visage of a young gool. "Please sir, I've lost my mother and I must eat. Won't you help me?"</p>
<p><b>No Skill:</b> Aghast, you draw your sword. You panic the crowd. In the confusion, the scared youngster slips away. You cannot catch him. [S1]</p>
<p><b>Weapon Use:</b> Your lightning draw staggers the beast, and you quickly dispatch him. The crowd is impressed with your skill and your willingness to do what had to be done. [D1/S1/Piety/<em>Respected</em> (1 turn)]</p>`,
	},
	2018: {
		index: 2018,
		text: `<p>You are surprised when a melancholy gooleh drags herself from a copse of woods and begs you to give yourself to her hunger. She seems so dispirited and pathetic that you cannot help but laugh. You draw your sword.</p>
<p><b>No Skill:</b> The beast has more resources than you thought. You are able to hold off her attacks, but she is relentless. Once she slashes you a couple times with her grime-encrusted claws, you decide this game is not for you. You run. [D1/<em>Diseased</em>]</p>
<p><b>Determined</b> (mandatory), <b>Enduring Hardship:</b> The fight is more serious than you guessed. The gooleh keeps coming despite your best efforts. In the end, it becomes a battle of endurance, but you outlast her and run her through. [D2/S1/Weapon Use]</p>`,
	},
	2019: {
		index: 2019,
		text: `<p>As you travel, you hear a mournful sound from over the next rise. Moving carefully, you see a wretched gooleh sobbing into her hands. A boy, dead and half-eaten, lies before her. Despite your fatigue and debilitations, you confront the beast, raging against her murder.</p>
<p><b>No Skill:</b> So ashamed is she at her deeds that she runs off into the brush. [D1/<em>Determined</em>]</p>
<p><b>Crippled, Wounded</b> (All mandatory): Noting your condition as well as your passion, the monster's sorrow is magnified. "I am not fit to live," she cries, "Allah take me now!" She seizes a nearby dagger and plunges it through her heart. [D1/S2/<em>Determined</em>]</p>`,
	},
	2020: {
		index: 2020,
		text: `<p>A shuffling sound disturbs your rest. You depart your campsite carefully, heading toward the noise. You discover a band of gools and gooleh, moving dissolutely through the night. They are weary and melancholy. It is apparent that they have not fed for some time. Having heard that the area was suffering from depredations by flesh-eaters in the area, you decide to follow to see where they are heading.</p>
<p><b>No Skill:</b> Fearful that you will be caught and consumed, you give the pack too much of a lead. You lose their trail in the darkness. [S1]</p>
<p><b>Wilderness Lore:</b> So astute are you in the wild that you return to your camp, pack your belongings, and still catch up with the monsters, tailing them for miles without their knowledge. They wind through difficult terrain and finally arrive at a large camp filled with their ilk. You hurry silently to the nearest town, returning with a troop of soldiers to slaughter the abominations. [D2/S1/Piety]</p>`,
	},
	2021: {
		index: 2021,
		text: `<p>You hear screams of fear. Moving toward the sound, you see a powerful flesh-eating ogress has cornered a young woman. She pleads for mercy, but the gooleh grimly attacks and devours her. Paralyzed with fear, you can do nothing but watch this horrid sight. Curiously, the gooleh appears dejected by her deeds. She drops to her knees and calls out in a guttural voice, "Allah, I do as is commanded by my nature. If you are displeased with my actions, I ask that you smite me down." She waits for a few moments, but nothing happens. She moves off consumed by her thoughts. You follow, vowing to exact Allah's retribution.</p>
<p><b>No Skill:</b> After a short while, the monster notices you. Disgusted with your hesitancy before, you stride forward, claiming Allah guides your actions. She scorns your mission, beats you soundly, and torments you for days before leaving you to die. [D1/<em>Insane</em>]</p>
<p><b>Stealth and Stealing:</b> You flit like a shadow after the beast, silent as the grave. After several hours, she drops to the ground and quickly falls into a deep sleep. You stealthily approach and slit her throat with your dagger. [D2/S1/Enduring Hardship]</p>`,
	},
	2022: {
		index: 2022,
		text: `<p>Wandering through a town market, you notice a cloaked figure moving swiftly, head bowed. As the creature pulls its hood lower, you spy a gnarled, gray-skinned hand. It's a gooleh! You follow, noting that the monster seems to be searching for something or someone. In time, she finds a group of resting city watchmen, separated from the throngs by a cart stacked high with rugs. She accosts the guards, and they leap back, drawing their weapons.</p>
<p><b>No Skill:</b> The gooleh appears to be trying to explain something to the soldiers but they will have no part of it. They stab her again and again with their spears. [S1]</p>
<p><b>Wisdom:</b> Something about the gooleh's manner intrigues you. Stepping between the spearmen and the monster, you hold up your arms. "Let her speak! Clearly she is distraught at something. So disturbed is she that she would converse with enemies superior in numbers and armaments. I, for one, am curious as to her motives." The guards pause enough to hear the gooleh's tale of woe. Her mate was killed by the scouts of a bandit army, sent to test this town's defenses. She seeks revenge and urges the watchmen to report the incursion. So warned, the town mobilizes and strikes down the outlaws. The gooleh escapes in the turmoil. The town headman stages an elaborate ceremony in your honor. [D2/S1/<em>Robe of Honor</em>]</p>`,
	},
	2023: {
		index: 2023,
		text: `<p>A crippled old man struggles with his burden. You pause to shoulder a large sack, easing his load. "The Almighty One inspires me to aid you, my friend," you say. "Let us walk to the mosque and pray to He Above All in gratitude."</p>
<p><b>No Skill:</b> Offended by your interference, the old man shrieks that he is being robbed. A crowd gathers and harsh words are spoken. You panic and rush to escape. The old man and others provide the town guard with your description. [D1/<em>Outlaw</em>]</p>
<p><b>Piety:</b> The ancient one is pleased by your manner and actions. "As Allah wishes, the mosque is indeed my destination," he explains. When you arrive, he gifts you with a sack of coins. [D2/W+1 (Max: Rich)/<em>Blessed</em>]</p>`,
	},
	2024: {
		index: 2024,
		text: `<p>A distinguished old merchant has heard of your deeds and prowess. He invites you to his home for a meal. When you arrive you find a gathering of important members of the local community. Conversation is lively and cultured, and you participate as best you can. Later in the evening, you suggest, "Let us all bow down to Allah, who has given us such bounty and good company."</p>
<p><b>No Skill:</b> Your attempts at wit during the course of the evening have been halting and uninformed. The manner of your suggestion conveys a sense of contempt for those around you. The group follows your lead (how can they refuse tribute to the Almighty One?) but they resent your implication. [D1/<em>Scorned</em>]</p>
<p><b>Wisdom:</b> The crowd is well pleased by your wisdom during the evening's lengthy conversations. Taken by the manner and appropriateness of your suggestion, they readily accept it as a fitting culmination to an enchanting gathering. [D2/S1/Courtly Graces]</p>`,
	},
	2025: {
		index: 2025,
		text: `<p>You are enjoying a sweet cup of Turkish coffee in a busy local restaurant. All seats are occupied excepting only the one other at your table, and an elderly man dressed in scholar's robs asks if he might impose on your reflections. You welcome the sage, and attempt to engage him in conversation. Anxious to hear of his studies, you say "I pray to Allah that we might become better acquainted."</p>
<p><b>No Skill:</b> You persistent questions and overbearing piety soon wear on the old man. He excuses himself and hurries out of the establishment. [D1]</p>
<p><b>Appearance, Seduction:</b> You pass a pleasant afternoon in the old man's company. He is clearly taken with your appearance, grace, and manners. He has learned much over the years and is happy to teach one so endearing as you. [D1/S2/Scholarship]</p>`,
	},
	2026: {
		index: 2026,
		text: `<p>You are accosted by the other, who asks for alms.</p>
<p><b>No Skill:</b> You give the other some money with the condition that they spend it wisely. You even follow them to make sure, but soon you are led to an abode of many unfortunates and the smell emanating from the area is overwhelming. Better, you decide, to simply have given away the money than to follow further. [S1/W-1 (Min: Poor)]</p>
<p><b>Scholarship, Luck:</b> There is something about the other that bothers you, yet you give some money and get a toothless smile as reward. The other hobbles away, but your instinct compels you to follow—and you end up in front of an opulent estate, where slaves come out and remove the decrepit clothing from the figure and replace them with rich robes. Rather than get angry, you laugh to yourself: certainly it was worth a few coins to learn from a true master. [S1/W-1 (Min: Poor)/Acting and Disguise]</p>`,
	},
	2027: {
		index: 2027,
		text: `<p>You see the other suspiciously steal away from a gathering crowd into a dark alleyway. You follow, assured of the other's guilt of some mischief.</p>
<p><b>No Skill:</b> The alley leads into several more alleys, and after a few turns, you are lost. Up ahead, you see a warm glow coming from a loud building. Therein, you see many denizens of all classes, but not the one you followed. You discreetly spend a few coins to obtain directions back to the center of town. [S1/W-1 (Min: Poor)]</p>
<p><b>Luck:</b> You are able to follow the other without being seen. Soon you are led to a broken down hovel—this must be the other's lair! You make note of the location, ready to bring guards for justice, when you hear children's voices. Peering through a crack in the wall, you see the other removing food from their robe and give it to a pack of children, who smile and laugh with joy at the bounty. Not all are fortunate under Allah's watchful eye. You leave a small donation before you depart. [D1/W-1 (Min: Poor)/Piety/You may discard a <b>Treasure</b> to gain Piety at Master level]</p>`,
	},
	2028: {
		index: 2028,
		text: `<p>You have followed a decrepit figure through sand and brush and see him halt at the edge of a large copse of trees. When the figure waves his hand and calls out a nonsensical word, the trees part to reveal an old city, with streets paved in gold. As you gaze at the marvel, you suddenly realize you are alone.</p>
<p><b>No Skill:</b> Quickly the trees come together, blocking your view—and your entrance. Unfortunately, you cannot remember the word to open the doorway and you depart, haunted by visions of wealth unattainable. [S1/<em>Envious</em>]</p>
<p><b>Scholarship:</b> The trees soon come together, but your sharp mind, used to reading ancient script, has grabbed hold of the word used to part the trees. You now have access to a trove of treasure and knowledge. [D1/W+3 (Max: Princely)/Wisdom]</p>`,
	},
	2029: {
		index: 2029,
		text: `<p>A strange outcropping of rock catches your attention. You investigate and notice strange symbols on one of the stones. As you run your fingers along them, the stones underneath part, revealing a paved walkway descending into the earth.</p>
<p><em>Do you dare enter?</em></p>
<p><em>If no:</em> Fearing the unknown, you depart. [S-1]</p>
<p><em>If yes:</em> Courageously, you make your way down. The stones come together above you, shutting out the light you are familiar with, but the walkway has its own illumination. On either side of the path you see ancient buildings. One such building has activity: light, laughter, people! Men and women in strange garb make merriment, and something compels you to join them.</p>
<p><b>No Skill:</b> However, you resist the call to revelry. The next thing you know, you are in the hands of guards who take you to the sultan. He wants the robe you are wearing, the one with encrusted jewels and he offers anything from his treasury. Unsure of what is going on, you do not refuse; and you end up very happy indeed. [D2/Search through the Treasure deck and take any one <b>Treasure</b>]</p>
<p><b>Fated</b> (mandatory): You join them without a second thought. Soon all memories of your past life fade away like wisps of smoke slowly rising in the air. Nothing is left of your old life but the ash of a previous existence, replaced by this moment, this eternally locked moment among these new people. [Death]</p>`,
	},
	2030: {
		index: 2030,
		text: `<p>An oasis provides you a much-needed respite from your travels. As you drink from the cool, clear pool, a glint of metal attracts your eye. You reach into the water and grab what appears to be a ring. With a loud "pop," the water drains away, revealing a sandy door. You look around and then open the door . . . and you find yourself alone, on the streets of an ancient city. There is no landmark here familiar to you. You are truly lost. [<em>Lost</em>/Have another player move you to any land space/Have an immediate encounter with Hidden City (Matrix E), choosing a reaction other than "Open"]</p>`,
	},
	2031: {
		index: 2031,
		text: `<p>In confidence, a man tells you that he knows of a household of secret heathens. He plans to rob them and needs an accomplice. You agree. While searching the house, you come to a locked room. He opens it and you discover a mysterious trapdoor, bedecked in jewels. As you move to open it to see what's inside, he pauses. "Why go further, my friend? Let us take what we have already and go."</p>
<p><b>No Skill:</b> Blinded by greed, you ignore his advice and open the door. Descending to the cellar, you find a pack of gools. You flee with nothing to show for your efforts. [D1/<em>Envious</em>]</p>
<p><b>Wisdom:</b> You see the value in his suggestion, and understand more than he intends. Carefully removing the door itself, you bear it out into the night. It fetches a tidy sum from a merchant who asks few questions. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2032: {
		index: 2032,
		text: `<p>A beguiling merchant sells you a map to a secret treasure cache. You find the location deep in a cave, but the way is barred by a trapdoor made of a mysterious metal and topped by a large gem. You attempt to raise the door, but nothing you try succeeds. Frustrated, you pry the gem from the door in an attempt to salvage something from the trip.</p>
<p><b>No Skill:</b> The gem turns out to be cut glass, worth only a few coins. The money you paid for the map is utterly lost. [S1/W-1 (Min: Penniless)]</p>
<p><b>Storytelling:</b> You have the gem appraised and it turns out to be worth little. Still, it is impressive looking and it inspires you. In each village that you visit for the next month, you spin a more and more elaborate tale about what that trapdoor hid, and what the gem meant. At the culmination of the story, you display the remarkable bauble to great applause. [D1/S1/Storytelling]</p>`,
	},
	2033: {
		index: 2033,
		text: `<p>You overhear two merchants whisper about the horde they have accumulated and how they buried it near an oasis in the desert. You are familiar with this area and you decide to wander out that way. You find a massive rock in the location that appears to have been moved recently. Although the stone is massive, you push against it, calling out Allah's name. Mysteriously, the rock moves revealing a trapdoor in the ground. Raising it, you are nearly overcome by the stench that drifts up from the opening. As you back away, you notice that the inside of the trapdoor contains an enormous jewel. What a prize that would be!</p>
<p><b>No Skill:</b> You are frustrated in your efforts to separate the jewel from the door, and too frightened to explore further. You march back to town defeated. [S1]</p>
<p><b>Stealth and Stealing:</b> Although the passage way is too daunting to explore, you turn your efforts toward securing the jewel. The casing resists your best tools, but the hinges prove more yielding. You drag the entire door back to town, and sell it to a wealthy thief. Let him devise how to separate the gem and door if he will. [D1/S1/W+1 (Max: Rich)/Quick Thinking]</p>`,
	},
	2034: {
		index: 2034,
		text: `<p>After many days of travel, you visit the local bathhouse, anxious for the peace and cleanliness it brings. The town is not a wealthy one, and the public baths are crude and ill-attended. So great is your need that you ignore the décor and dip into the warm waters. Luxuriating, you drift off to sleep. When you awaken, you find yourself alone. Calling out, no one appears. Worse, the attendants have taken your clothes and your belongings. You wander the halls for a while, but the stillness is absolute. The very last room is behind a locked door. Angered, you beat on it until it smashes open. You find a jeweled tile trapdoor in the floor. Mysterious glyphs cover the surface.</p>
<p><b>No Skill:</b> The door perplexes you and helps your situation not one iota. You are forced into the street to buy clothing. Your nakedness is shameful. [S1/W-1 (Min: Penniless)/<em>Scorned</em>]</p>
<p><b>Scholarship:</b> With time, you piece together the secret of the glyphs. When pushed in the proper order, with the proper timing and the proper chanting, the jewels unlock the door. Inside you find several scrolls covered in the same glyphs—and a map. [D2/S1/Magic/Opportunity to enter the City of Brass]</p>`,
	},
	2035: {
		index: 2035,
		text: `<p>You have been captured by brigands! The vile slavers toss you and a number of other poor innocents into the lower reaches of a cavernous complex far from civilization. Overconfident, your oafish jailor succumbs to drink and loses consciousness. You rally the other prisoners and attempt an escape. The bulk of the bandits are closer to the surface so your only route is deeper into the caves. In time, you reach a dead end, and the running boots of the alerted slavers begin to echo closer! You foot sounds hollowly on the floor. Scrambling madly, you and the others dig in the dirt, and discover a large trapdoor, held closed by a jeweled clasp. You open it to find food, weapons, and treasure... but no escape.</p>
<p><b>No Skill:</b> You and your companions surrender to the slavers. [D1/<em>Enslaved</em>]</p>
<p><b>Quick Thinking:</b> Propping the old wooden door open with barrels of foodstuffs, you hand out weapons. On your orders, the prisoners take up defensive positions behind the cover of the raised trapdoor. So fortified, you fight off the initial assault. The bandits also realize they can't starve you out because you have plentiful provisions. A day later, they fall to fighting among themselves. In a week, you are free to return to your travels. [D2/S1/Weapon Use]</p>`,
	},
	2036: {
		index: 2036,
		text: `<p>Exploring the ruins of an ancient city, half buried in sand, you discover the subfloors of a building still intact. Pushing through the gloom, dust, and debris, you find a large circular chamber, its ceiling, walls, and floor covered in arcane symbols. A palpable fear seems to emanate from the room. Swallowing your panic, you step inside. The symbols on the floor fade to reveal a trapdoor, edged in gems and worked with silver. Power runs through the place, if only there was a way to use this might.</p>
<p><b>No Skill:</b> Despite your pokes and prodding, the trapdoor cannot be budged. The glyphs are similarly useless. [S1]</p>
<p><b>Magic:</b> Your sensitivity to magic alerts you to the lines of force tied to the symbols on the walls. After a few hours of study, you discern what positions you must take about the room and what words of power must be whispered. You perform the ceremony flawlessly and the door yawns open. Inside are numerous magical tomes and an item of great value. [D2/S1/Magic/<b>Treasure</b>]</p>`,
	},
	2037: {
		index: 2037,
		text: `<p>You purchase a tarnished belt buckle from a disreputable merchant for a pittance. As you clean it, you discover that it is gold, plated in a base metal. You carefully chip away at the coating to reveal the minor treasure beneath. You don the item, pleased with new appearance.</p>
<p><b>No Skill:</b> Although the golden buckle is fine, it cannot make up for your physical shortcomings. [D1]</p>
<p><b>Appearance, Seduction:</b> Your attractiveness is enhanced by this shiny bauble. You soon encounter a potential mate. [D2/<em>Love Struck</em>]</p>`,
	},
	2038: {
		index: 2038,
		text: `<p>A secret admirer sends you a package. It is an ivory mask, trimmed in silver. This is a valuable gift indeed! Determined to find your benefactor, you don the mask and attend the next day's masquerade celebration. You pass a pleasant several hours in conversation and revelry, until a servant approaches and asks you to join the one who gave you the mask in an antechamber. Pleased by your cleverness, you follow. Your admirer, unfortunately, turns out to staggeringly ugly.</p>
<p><b>No Skill:</b> You flee in horror and disappointment. [D1/<em>Grief Stricken</em>]</p>
<p><b>Acting and Disguise:</b> As you donned your mask, you adopted a different voice and set of mannerisms. You claim that you bought the mask from an adventurer who needed money for his travels. The other is saddened at what he believes is a mistaken identity and bids you good night. [D2/S1/Quick Thinking]</p>`,
	},
	2039: {
		index: 2039,
		text: `<p>On your travels, you come upon the wreckage of a caravan. The guards have been slain, the wagons looted, and the leader of the merchants lies wounded and senseless. When you tend to him, he awakens and blesses your arrival. He tells you of a secret compartment in the bottom of the smallest wagon. Therein rests a fur robe—his most valuable possession. He promises you a reward if you carry him and it to the next city. Midway through the journey, burdened by the portly merchant and wearing his heavy belonging, you question the wisdom of your agreement.</p>
<p><b>No Skill:</b> The sojourn is too difficult. In time, the merchant must choose between himself and his robe. The garment is abandoned, and your reward lessened for it. [S1/W+1 (Max: Poor)]</p>
<p><b>Enduring Hardship:</b> You struggle through magnificently. Safely arriving at the next city with both the man and his prized object, you are hailed by his family as a hero. You are feted, praised, and sent on your way much wealthier. [D2/S1/W+1 (Max: Rich)/<b>Treasure</b>]</p>`,
	},
	2040: {
		index: 2040,
		text: `<p>Fishing to supplement your meager stores, you hook a small iron box. Eagerly opening it, you find a small sack of coins and a sparkling crystal amulet that pulses with an inner light.</p>
<p><em>You may take the coins, the amulet, or both.</em></p>
<p><em>If you take only the coins:</em> A wise man knows to leave the things of magic to themselves. [D1/W+1 (Max: Respectable)/Wisdom]</p>
<p><em>If you take only the amulet, or both:</em> The coins are all well and good, but the real prize here is the amulet. With trembling fingers, you raise it over your head and drop it upon your neck and shoulders. A sudden crash sounds, and an angry Jinn appears. "You dare disturb my rest, mortal! You shall be punished."</p>
<p><b>No Skill:</b> The magical being seizes you and you both disappear in a puff of acrid smoke. [D1/<em>Ensorcelled</em>]</p>
<p><b>Weapon Use:</b> Although the Jinn is more powerful that you in the magical arts, your prowess with the sword wins you the day. The entity grants you one wish. [D1/S1/<em>Blessed</em>]</p>`,
	},
	2041: {
		index: 2041,
		text: `<p>Wandering the bazaar, you are accosted by a merchant who shows you a remarkable wooden box. With several deft motions, he shows you how to open it, and then lock it shut. Enchanted with the craftsmanship, you are determined to have it.</p>
<p><em>Roll two dice and add one each for Bargaining and Evaluation, Beguiling, and Appearance:</em></p>
<p>❖ 2–8: You cannot come to an agreement with the merchant. You leave sorely disappointed. [D1/<em>Envious</em>]</p>
<p>❖ 9+: You swiftly conclude your business with the merchant and carry your new-found treasure away. You waste no time manipulating the box as he showed you. As you expected, it is empty—the box itself is your treasure. Still, the inner dimensions seem odd to you.</p>
<p><em>You can leave it be, or use a dagger to pry at the bottom:</em></p>
<p><em>If you leave it be:</em> The box gives you great pleasure for several years, but you always wonder what it truly contains. [S1]</p>
<p><em>If you pry at it:</em> You are more forceful than you wished, and shatter the item in your clumsy attempts. You disappointment is tempered, however, when a small rolled map falls from the secret compartment you opened.</p>
<p><b>No Skill:</b> The map is strange and indecipherable. It is worthless to you, and you can get only a few coins by selling it. [S1]</p>
<p><b>Wilderness Lore:</b> The map shows a number of different places that you have visited, or that you have always wished to visit. Better yet, it shows a number of hidden routes to these places, making travel swift and safe. [D1/Opportunity to enter the Sepulchre of Solomon]</p>`,
	},
	2042: {
		index: 2042,
		text: `<p>After many days of travel through the desert, you come to a lovely oasis. The vegetation is lush, the waters clear and cool. As you bend to drink, you spy a silver chest below the surface. After slaking your thirst, you succumb to your curiosity and retrieve the shiny box. When you open it, a cloud of purple vapor rises, coalescing into a vague human form. "Ah dearest savior, I have waited so many years for you to attend me." The smoke solidifies into a beauteous being—the one you have longed for these many years.</p>
<p><b>No Skill:</b> Although you do all in your power to please the other, your efforts are halting and insecure. After one night of frustration, the dreamlike being departs. [D1/<em>Grief Stricken</em>]</p>
<p><b>Seduction:</b> You give the object of your desire great pleasure, and receive that ecstasy doubled in return. In the morning, the other is gone but you have been transformed by your bliss. [D2/S1/Appearance]</p>`,
	},
	2043: {
		index: 2043,
		text: `<p>As you cross a great desert, you become lost. One evening, as the sun sets, it leaves a burning pyre on the horizon. With nowhere else to go, you approach it. A mighty marid is encased in the fire. In a booming voice, he asks that you free him by using the remainder of your water on the flames.</p>
<p><em>You can do so, or leave the being to his prison:</em></p>
<p><em>If you walk back into the desert:</em> A few days later, you arrive at a settlement. You tell your tale, but few believe you. [S1]</p>
<p><em>If you douse the flames:</em> The grateful efreet gifts you with a magical ring. "Put it on and it will take you any place your heart desires." You slip the ring over your finger, and a dozen doors appear in the sand. The marid vanishes, leaving behind an echoing laughter.</p>
<p><b>No Skill:</b> You pick a door at random and enter. It takes you home to Baghdad. [D1/Move to Baghdad]</p>
<p><b>Luck:</b> You consider all the places you would like to visit, envision one of them, and step through a door. It takes you to a fine home there. The slaves bow down to you as their new master. [D2/W+2 (Max: Rich)/Move to any city space]</p>
<p><b>Magic:</b> Studying the ring and the glowing portals, you understand a great deal about the magic inherent in them. Confident in your power, you step through the least of the doors, arriving in the fabled City of Brass. [D2/<b>Seal Ring</b>/Move to the City of Brass and have an immediate encounter]</p>`,
	},
	2044: {
		index: 2044,
		text: `<p>As a result of your daring, and the evidence you uncover, a wicked Vizier is revealed and beheaded. The Sultan grants you a choice of one item from the Vizier's possessions. When you arrive at the Vizier's palace, an old slave thanks you profusely for delivering the household from bondage to the evil man. As he washes your feet, he whispers that among the treasures to be found in this place, the greatest is a portal to an enchanted kingdom. You question him further and he shows you a beaten brass lamp. It appears worthless compared to the gold and jewels that fill the palace.</p>
<p><em>You can take the lamp or something that appears much more valuable:</em></p>
<p><em>If you take something else:</em> The treasure you choose is indeed worth much, but it carries a taint from the wicked Vizier. [D1/W+1 (Max: Rich)/<em>Accursed</em>]</p>
<p><em>If you take the lamp:</em> Taking the old slave at his word, you accept the lamp. He shows you the gestures necessary to open the door to the kingdom, but warns that those who inhabit that place are cultured. They expect the same from their guests.</p>
<p><b>No Skill:</b> You wander the kingdom and see many wondrous sights. Your interactions with the residents, however, are lacking. To teach you better manners, they set a task before you. [S1/<em>Under Geas</em>]</p>
<p><b>Courtly Graces:</b> The kingdom is all the old slave described. The buildings are glorious, the streets are paved in gold, and the denizens are fascinating. Your grace and manners please them, and they reward you with enchanted good fortune. [D1/S1/Luck]</p>
<p><b>Magic:</b> You study the lamp for a time and learn a great deal about the enchantments placed on it. Fearful that your manners will displease the residents, however, you barter the item to the new Vizier. This brings you great favor with him. [D2/W+1 (Max: Rich)/Magic/<em>Respected</em>]</p>`,
	},
	2045: {
		index: 2045,
		text: `<p>Last night, you had the most wondrous dream. In it, you chased an enchanting being, the sum of all your earthly desires. You glided through a glorious garden, with brilliant flowers entwined about the trees and running along the ground. Multicolored birds flew and sang cheerful songs. After a breathtaking pursuit, you caught your love in a pleasant meadow. As you bent to give the other a kiss, you found yourself holding a strangely glowing tiara. A voice sounded, "Come to me, my love. Use the crown." When you awoke, you found a beaten tin headpiece among your things. Thinking of the dream, you wonder if it could be the tiara.</p>
<p><b>No Skill:</b> Donning the item, you are transported to the beauteous garden. There you find your love waiting for you. You are not skilled or experienced enough to give pleasure, however. The landscape dissolved and you are left bereft. [D1/<em>Accursed</em>]</p>
<p><b>Seduction:</b> You place the item on your brow and the world around you transforms. You re-enact your chase and capture. When you kiss your love, it is but the first of many. Your night of bliss is extraordinary. You awaken to find the headband gone. In the days that come, however, you notice you now possess an easy way with people. [D1/S1/Beguiling]</p>
<p><b>Magic:</b> You recognize the power inherent in the meager item. You bring the headpiece to the Sultan and explain the pleasure it can grant to those of sufficient skill. He is greatly pleased by your knowledge, ability, and fealty. He names you Vizier. [D2/S1/<em>Vizier</em>]</p>`,
	},
	2046: {
		index: 2046,
		text: `<p>The leader of the brigands gives a snort and pokes your chest hard with one ring-covered finger. "What could a wretch like you possibly do to aid the likes of us?"</p>
<p><b>No Skill:</b> You admit you have no prior experience in the world of brigandry, but offer to help in any way you can. The leader puts you in charge of cleaning up after all their camels. [S1/Enduring Hardship/<em>Enslaved</em>]</p>
<p><b>Wisdom:</b> You offer to devise a brilliant scheme for the brigands' next raid—in exchange for your freedom, and just a bit of gold. [D1/S1/W+1 (Max: Rich)/Bargaining and Evaluation]</p>`,
	},
	2047: {
		index: 2047,
		text: `<p>The brigands encircle you, scimitars drawn, teeth bared, eyes afire. One steps forward, points his blade at you and says, "Give me one good reason I should spare your life."</p>
<p><b>No Skill:</b> You offer to serve the brigands on their next raid, with no expectation of compensation beyond your freedom. The leader agrees, and true to his word, returns you to your travels when the job is done... but by then, you are a wanted man. [D1/<em>Outlaw</em>]</p>
<p><b>Beguiling:</b> You convince the brigand leader that you are capable of providing an effective distraction as a prelude to a successful raid. When the time comes to perform your task, however, you simply make good your escape into the night, leaving the brigands to face the merchant's guards unprepared. [D2/S2/Quick Thinking]</p>`,
	},
	2048: {
		index: 2048,
		text: `<p>The leader of the brigands sizes you up a moment before bringing the point of his scimitar to rest beneath your chin. "Prove that you know your way around a blade," he says, "And you just might be of use to me."</p>
<p><b>No Skill:</b></p>
<p><em>You can duel with him or refuse:</em></p>
<p><em>If you duel with him:</em> You are no match for the brigand leader's skill with a scimitar, but you fight with courage and his men are entertained. The brigands leave you alive, but bereft of all possessions, naturally. [S2/Reduce your Wealth to Beggar, but gain D1 for each level lost in this way]</p>
<p><em>If you refuse:</em> One of the brigands tosses a scimitar at your feet. "Let it lie, if you like," says the leader, "But armed or not, you will fight me!" You are no match for his prowess, and he leaves you not only bereft of all possessions, but bloodied for your cowardice, as well. [D1/S1/W=Beggar/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> To the surprise of all assembled, you manage to duel the brigand leader to a draw. He allows you to assist him on his next raid, which earns you not only a fair portion of the spoils, but a bounty on your head, as well. [D2/S2/W+1 (Max: Rich)/<em>Outlaw</em>]</p>`,
	},
	2049: {
		index: 2049,
		text: `<p>The gang of brigands parts before the confident stride of its leader, who emerges from among his cohort to face you. He says nothing, but simply stands and stares expectantly.</p>
<p><b>No Skill:</b> Unsure as to how best to honor the brigand, you decide to offer a deep bow with a great flourish of the arm for added effect. This offends the criminal leader greatly, and he responds by severing the offending arm with his scimitar and replacing it with a tin hook. He then returns your bow and takes his leave. [D1/S2/Wisdom/<em>Crippled</em>]</p>
<p><b>Scholarship:</b> You recognize this particular band of brutes from your studies, and seem to recall that the gang responds favorably to protracted displays of groveling. You throw yourself at the brigand leader's feet, and one protracted display of groveling later, you are returned to your travels unharmed, and with a purseful of silver to show for your timely humility! [S1/W+1 (Max: Poor)/Acting and Disguise]</p>`,
	},
	2050: {
		index: 2050,
		text: `<p>As you draw near, you find the brigands enmeshed in a bitter dispute over which brigand's legacy is greatest; whose blade is fastest, whose name strikes the greatest fear into the hearts of the wealthy and corrupt. Viewing your timely arrival as a sign of Fate, the brigands immediately demand that you settle the matter.</p>
<p><b>No Skill:</b> In order for you to know who is greatest, you reason, you must witness each brigand's prowess first-hand. You make them spend the evening engaged in trials of speed, swordsmanship, and savagery, all designed to set brigand against brigand. When the last of the trials concludes, you render your verdict—which immediately enrages all those who felt they should win but did not. The brigands chase you from their camp, cursing your name and shouting threats of violent revenge. [S2/Bargaining and Evaluation/<em>Pursued</em>]</p>
<p><b>Storytelling:</b> Pulling out your parchment and your quills, you offer to immortalize the story of the entire gang's many, thrilling exploits. You spend the evening hearing testimonials around a fire, and come morning, the brigands leave you to the business of transforming their deeds into the stuff of legend. [D1/S1/W+1 (Max: Rich)/Storytelling]</p>`,
	},
	2051: {
		index: 2051,
		text: `<p>The brigand leader informs you that there are only two ways for an outsider to prove his honor to the gang: One must either marry a relative of one of the brigands, or else best one of the brigands in unarmed combat.</p>
<p><em>You can marry or you can fight:</em></p>
<p><em>If you marry:</em> With a deep bow (which conceals an even deeper sigh), you consent to take one of the brigand's relatives for a spouse. Only when the would-be spouse is brought forward do you see the error of your ways, for this individual is truly the ugliest person you have ever laid eyes on! Allah, be merciful! [D2/S1/Enduring Hardship/<em>Married</em>]</p>
<p><em>If you fight:</em> The fight is long and exhausting, but in the end it is you who stands tall. The brigand leader praises your valor and happily informs you of a tradition among his tribe: One who bests a tribe member in unarmed combat must take one of that fallen member's unwed relatives for a spouse. [D1/S2/Enduring Hardship/<em>Married</em>]</p>`,
	},
	2052: {
		index: 2052,
		text: `<p>You spy the band of brigands standing in a semi-circle, an array of stones laid out before them. With a wooden stick in hand, one slashing his own arm to bring forth blood, with which he draws elaborate patterns on the stones. You step forward and ask what this strange ritual is supposed to accomplish.</p>
<p><b>No Skill:</b> The gang responds to your intrusion by robbing you, beating you, and leaving you for dead. [S2/<em>Wounded</em>/Reduce your Wealth to Beggar, but gain D1 for each level lost in this way]</p>
<p><b>Piety:</b> Further, you implore the brigands to think of their faiths! Allah cannot look kindly for using foul magics to plan their crimes! Surprisingly, a few of the brigands take your lesson and flee at once; with them gone, the remaining brigands see no choice but to disband. Allah be praised! [D2/S1/Luck]</p>`,
	},
	2053: {
		index: 2053,
		text: `<p>While sailing on board a fishing vessel, a gang of brigands emerges from the cargo hold. The brigands quickly take over the ship, but at a high cost to the crew. With the ship secured the brigands bring you before their leader, who grants you a single question.</p>
<p><b>No Skill:</b> You ask if he will spare your life, and he responds by tossing you overboard. It takes you hours to reach land, but at least you're alive. [D1/S1/Wisdom]</p>
<p><b>Seamanship:</b> You ask if he has need of another crew member, knowing full well that he does. He agrees to spare your life, and even pay you a small sum, in exchange for helping him man his stolen ship. [D1/S2/W+1 (Max: Rich)/Bargaining and Evaluation]</p>`,
	},
	2054: {
		index: 2054,
		text: `<p>While traveling through an arid wasteland you encounter a band of desperate brigands. They seem low on supplies and begin eyeing your saddlebags intently.</p>
<p><b>No Skill:</b> You ask the brigands if they wish to buy some of your water, but brigands will be brigands, and they respond by just robbing you and leaving you for dead. [S2/Reduce your Wealth to Beggar, but gain D1 for each level lost in this way]</p>
<p><b>Wilderness Lore:</b> Sensing what's to come, you ask the brigands if they will consider an alternative to robbing you and leaving you for dead: You offer to show them the way out of the wasteland, by way of an oasis where they may refill their water skins, in exchange for your life (and a modest sum, of course). [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2055: {
		index: 2055,
		text: `<p>While walking around the Sultan's fair port, you spy a brigand that you recognize as a member of the Cleanfoot Gang, a group of petty thieves obsessed with cleanliness. You wait until the thug enters a crowd, and then move up to walk behind him. At the same time as you reach for his purse, you unleash a massive bout of coughing. Disgusted, the thief runs away, ignorant of his loss.</p>
<p><b>No Skill:</b> A nice haul for such a simple trick! [S1/W+1 (Max: Respectable)/Stealth and Stealing]</p>
<p><b>Acting and Disguise:</b> You follow the thug back to the Cleanfoot Gang's hideout. Once you know the location, you disguise yourself to appear as a diseased leper and wait for most of the gang to leave. You then enter the hideout and throw yourself bodily onto the gang's loot, causing the remaining brigands to run screaming from the place. [S1/W+2 (Max: Rich)]</p>`,
	},
	2056: {
		index: 2056,
		text: `<p>While traveling through a ravine off the beaten path you come upon a gang of brigands huddled around a pile of gold and jewels, the spoils of a recent raid.</p>
<p><b>No Skill:</b> You try to set up an elaborate distraction that would leave the camp empty, but the brigand leader spots the ruse at the last second and catches you trying to make off with the loot. For your temerity, the leader personally removes your thieving hand before robbing you and sending you on your way. [S1/<em>Crippled</em>/Reduce your Wealth to Beggar, but gain D1 for each level lost in this way]</p>
<p><b>Magic:</b> Donning a gravely serious look, you approach the brigands, arms outstretched, hands gesticulating. "Behold the Mystic Veil of Umm-Kalzoun!" you intone. "Criminals, your final hour is at hand!" Out of "thin air" you pull a line of veils tied end to end, each one a different color of the rainbow. The brigands take one look at the "magic veil," drop their swords, and run for the hills—leaving the loot behind. [S1/W+2 (Max: Rich)/Acting and Disguise]</p>`,
	},
	2057: {
		index: 2057,
		text: `<p>While traveling at night you gain the crest of a hill and discover a brigand camp in the valley below. Most of the gang is asleep, leaving only two guards quietly tending a fire.</p>
<p><b>No Skill:</b> When the time is right, you throw a stone to get one of the guards to move away from the camp. You then move in on the other one and knock him senseless before he can raise the alarm. Trying to take more loot than you can carry causes the first guard to return before you've made good your escape, and he wakes the entire gang to action. You manage to get away, but now they're out for blood! [S1/W+2 (Max: Rich)/<em>Pursued</em>]</p>
<p><b>Quick Thinking:</b> At the edge of the camp you spy what looks like a barrel... It is lamp oil! Your mind racing, you circle around to the far side of the valley and sneak up to the camp's perimeter. With a long branch you tip the barrel over, right into the fire! The resulting conflagration sets the camp ablaze, and in the chaos you escape with the loot. [D1/S1/W+2 (Max: Rich)]</p>`,
	},
	2058: {
		index: 2058,
		text: `<p>"You wish to pay honor to us? In our world, the only honor is dishonor. If you are not of our people, then away with you!"</p>
<p><b>No Skill:</b></p>
<p><em>You can pretend to be a fierce outlaw from another land, or you can apologize and head on your way.</em></p>
<p><em>If you pretend:</em> [Go to paragraph 1384]</p>
<p><em>If you head on your way:</em> True to their word, they let you go—in a manner. They mistreat you severely before tossing you away. [D1/S1/W-2 (Min: Poor)/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> "Oh, so?" you cry, pulling your sword. The confidence in your mien impresses them, and they laugh. "This one is no criminal, but he has a sting!" With that, they turn and go. [D1/S1/<em>Determined</em>]</p>
<p><b>Outlaw</b> (mandatory): Proudly you declare the misdeeds that constitute your criminal past. [You cannot resist embellishing, but they are too impressed to notice.] They accept you as one of their own and invite you to ride with them for a while. [S1/Stealth and Stealing]</p>`,
	},
	2059: {
		index: 2059,
		text: `<p>You come across a band of brigands engaged in raucous celebration of a recent raid. The wine flows steady and the sounds of their merriment echo across the valley floor. Why the celebration, friends?" you inquire. The brigands tell you of their brazen daylight raid on a corrupt merchant who, through unconscionable usury, had drained the poor of both their dignity and their earnings.</p>
<p><b>No Skill:</b> "Although you do not generally drink alcohol, you raise a mug and toast the honor of their deeds. [D2/S1/Bargaining and Evaluation]</p>
<p><b>Courtly Graces:</b> Moved by their conviction, you offer to represent the gang as emissary to the common folk, to spread the word of the brigands' heroic deeds in your travels. The gang honors you with a toast and with recitation of an oath of acceptance and respect. [D2/S2/<em>Respected</em>]</p>`,
	},
	2060: {
		index: 2060,
		text: `<p>You spy a band of brigands camped around a roaring fire. You walk forward boldly and offer greetings to them, praising them for their obvious joyful spirit. "Entertain us!" the leader laughs, "and we shall share with you a portion of our spoils!"</p>
<p><b>No Skill:</b> You don't consider yourself an entertainer by any means, but you do know a handful of jokes, which you recount for the brigand leader and his men over mugs of wine. After an especially bad joke, the leader throws up his hands. "All right, all right!" he says. "We give up! Take the money! Just stop telling jokes!" [S1/W+1 (Max: Rich)]</p>
<p><b>Storytelling:</b> You honor the brigands' request by regaling them with tales of the Djinn Caliph and his nine hundred anthropophagic steeds. They shower you with thanks for the great jest. [D1/S2/W+1 (Max: Rich)]</p>`,
	},
	2061: {
		index: 2061,
		text: `<p>The brigands stagger to and fro, their numerous empty mugs and wineskins strewn haphazardly about the scene. One is on his knees, making nauseating wretching sounds.</p>
<p><b>No Skill:</b> "Tsk, tsk," you say, wagging a finger at the drunken men. "I pray you see the error of your ways... come morning." The ones who can still ambulate rise and chase you away from their camp, waving swords and spitting curses at your back as you flee. [S1]</p>
<p><b>Piety:</b> "For shame!" you shout. "The Koran warns us, 'Approach not prayers with a mind befogged.' Steal to survive, if you must, but you insult the Most High by this wanton intoxication!" Suddenly sobered, the brigands thank you for reminding them of their faith, and politely ask that you join them in prayer. [D1/S1/Luck]</p>`,
	},
	2062: {
		index: 2062,
		text: `<p>Having spent the evening carousing with a group of men, you are shocked to see them up and girding for battle come morning. It soon becomes apparent that these men were actually brigands all along, and that they are now preparing to launch a raid! Before they leave, the brigand leader asks if you'll pronounce a blessing upon him and his men.</p>
<p><b>No Skill:</b> You recite a quick verse or two from the Koran, hoping that your derogation of faith will go unnoticed. It does not. [D1/Lose Piety]</p>
<p><b>Scholarship:</b> You lay out an elaborate and articulate theological explanation for how you cannot technically bless the brigands' efforts without jeopardizing your relationship with Allah, but it all sounds like a blessing to the brigands, so they are just as pleased. [D1/S1/Quick Thinking]</p>`,
	},
	2063: {
		index: 2063,
		text: `<p>While carousing with a band of brigands one evening, it slowly dawns on you that they plan to engage in a raid on a passing merchant caravan the following morning.</p>
<p><b>No Skill:</b> You spend the bulk of the night in prayer, forgoing sleep in the hope that Allah will hear your plea. You pray for the brigands to see the error of their ways, but come morning they ride off to raid the caravan just the same. [S1/Piety]</p>
<p><b>Wisdom:</b> Once you realize what the brigands are planning, you decide to keep them up talking, plying them with more and more wine throughout the night. Most are so drunk by the time they fall asleep, the gang as a whole is terribly late to rise the next morning. As a result, the brigands miss their chance to intercept the merchant caravan. Without ever lifting a finger, you have thwarted the brigands' raid! [D1/S2/Beguiling]</p>`,
	},
	2064: {
		index: 2064,
		text: `<p>You pass through a small village that is preparing for a large festival. The locals relate how tradition demands that an outsider don a veil to play the part of a sex-changing imp in the festival's play, and they offer to pay you for your trouble if you will but humor them.</p>
<p><b>No Skill:</b> Wanting to be accommodating, you agree to wear the costume. But after the play is ended, you remove it to find that you have truly transformed into the opposite sex! True to their word, the villagers pay you for your "trouble" and send you on your way. [S2/W+1 (Max: Rich)/Wisdom/<em>Sex-Changed</em>]</p>
<p><b>Scholarship:</b> Having read about this particular village, you know the stories of the lone traveler who "enters as man but leaves as woman." You bow humbly before the village elders, saying, "Regrettably, I must decline. You see, I was born in this selfsame village, so I cannot possibly be the 'outsider' you seek." [D1/S1/Quick Thinking]</p>`,
	},
	2065: {
		index: 2065,
		text: `<p>You find occasion to return to the same village where you had once saved the locals from a band of marauding brigands. They are obviously working hard together on some task, and you immediately fall in among them to help. When you are at the center of the village, you see they are erecting a statue.</p>
<p><b>No Skill:</b> When you help lift the statue's head into place, you are shocked to see your own face staring back! The statue is dedicated to you! [D2/S1/Appearance/<em>Beloved</em>]</p>
<p><b>Piety:</b> Shaking your head somberly, you clear your throat and admonish them. "Lay not your faith upon false idols, brothers and sisters," you implore. "There are other, better ways to honor your heroes and loved ones." The townsfolk are saddened but moved by your words, so they decide to abandon the statue in favor of a simple memorial stone. [S1]</p>`,
	},
	2066: {
		index: 2066,
		text: `<p>On the way to a distant city you encounter an old man walking on the road. His gait is slow and his back bent from the heavy burden he carries. As you are headed in the same direction, you offer assistance. He is surprised.</p>
<p><b>No Skill:</b> You offer to take the old man's burden and strap it to your horse. "Why would you do that for me?" asks the man. "Because," you reply, "It is the right thing to do." [D1/S1]</p>
<p><b>Wisdom:</b> You offer to trade places with the old man, so that he rides atop the horse and you walk. "Why would you do that for me?" asks the man. "Because," you reply, "It is the right thing to do... and the wise way to do it." [D2/S1/Bargaining and Evaluation]</p>`,
	},
	2067: {
		index: 2067,
		text: `<p>You stop at a roadside fruit vendor who fears that Allah has frowned upon her crop, due to its uncharacteristic appearance this season. You convince the vendor that you can say a blessing over her crop that will insure Allah's favor.</p>
<p><b>No Skill:</b> You continue, "All it will take is a sample of each fruit to be blessed." She freely gives you one of each fruit she has to sell, but your ruse plagues you with guilt thereafter. [S1/Lose Piety]</p>
<p><b>Wilderness Lore:</b> As you start to pray, you take a closer look at the fruit and begin to laugh. When the vendor looks to you for an explanation, you happily relate to her that the unusual coloration is merely a function of the weather patterns in the off-season, and that her crop is just fine. She thanks you profusely and bestows a blessing upon you. [D1/S1/<em>Blessed</em>]</p>`,
	},
	2068: {
		index: 2068,
		text: `<p>The caravan you are traveling with stops for the night alongside another caravan, one filled with travelers from the East. They build a large communal fire and invite everyone to make merry.</p>
<p><b>No Skill:</b> Having heard the stories of ways of this people, you pray to Allah to guide and protect your caravan-mates from the temptations and excesses of the evening. You forget to include yourself in the prayer, however, and you wake the next morning with a terrible headache and substantially fewer coins. [D1/S1/W-1 (Min: Penniless)]</p>
<p><b>Luck:</b> The travelers need supplies and your caravan needs funds, so you pray to Allah for good fortune and partake in their games of chance. To the surprise of all assembled, you actually win more than you lose! [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2069: {
		index: 2069,
		text: `<p>While playing host to an Egyptian family, their children pull out wooden figures and begin playing a game they call "Jackals and Hounds." One of the locals sees the children and screams, "Idolatry!" Within minutes, an increasingly angry mob is amassing... You pray to Allah for a swift and peaceful resolution, and implore the crowd to disperse.</p>
<p><b>No Skill:</b> No harm comes to the family, but they are asked to leave and their game pieces are destroyed. [S1]</p>
<p><b>Weapon Use:</b> When the crowd remains, you draw your scimitar and stand side-by-side with your Egyptian friend. After a tense moment, the mob one by one finds pressing business elsewhere. [D1/S1/Piety]</p>`,
	},
	2070: {
		index: 2070,
		text: `<p>Out in the desert one night, you find yourself sharing a camp fire with another lone traveler. The man tells you that it is customary in his tribe for two travelers to tell one another stories until they both fall asleep.</p>
<p><b>No Skill:</b> You agree to indulge the stranger's custom, and dig deep into your repertoire of tales in order to insure that he falls asleep long before you do. Once he's sound asleep, you filch his coins and quietly take your leave of the camp. [S1/W+1 (Max: Respectable)]</p>
<p><b>Storytelling:</b> You tell the stranger a terrifying tale of how this very region of desert is haunted by a vengeful spirit that visits travelers in their sleep and scares them to death. By the time you're done, the stranger is practically begging you to tell him how to appease or avoid this vengeful spirit. And you're more than happy to oblige... for a price. [D1/S2/W+1 (Max: Rich)/<em>Beguiling</em>]</p>`,
	},
	2071: {
		index: 2071,
		text: `<p>While you travel with a tribal caravan, an ugly inter-family dispute erupts. Before long, a duel is soon in the offing. One of the two duelists, however, is very sickly. Tribal law allows an outsider to step in as a champion for one of the two sides.</p>
<p><b>No Skill:</b> "I will champion his cause," you say. "But if I am to risk my life for another's honor, I must be compensated." The family gathers together a fair sum to pay you. Then, with that money in hand, you bribe the other fellow to throw the fight to you. Unfortunately, in his attempt to make the fight convincing, he runs his sword through your leg before conceding. [S1/W+1 (Max: Respectable)/<em>Wounded</em>]</p>
<p><b>Bargaining and Evaluation:</b> Where others see a threat, you see an opportunity. When handed your blade, you refuse it. "Today, we mend the wounds of the spirit not by making wounds of the flesh, but by speaking as men." You arrange a series of payments between the two families to recompense each for the many offenses they feel they have suffered; they are so grateful they don't notice that you have skimmed nearly a third of the money for yourself. [D2/S2/W+2 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	2072: {
		index: 2072,
		text: `<p>Hiking your way across a lonely mountain pass, you are surprised to come upon a woman and her daughter, both leaning out over a yawning precipice. When you ask what brings them here, the mother tells you that they must climb down to the nest of the Roc, a giant bird of myth and legend, and steal one of its eggs, for only the yolk of a Roc egg can heal the young girl of the illness which she says is consuming her from the inside out.</p>
<p><b>No Skill:</b> Believing the hand of Fate to be at work in your life, you eagerly volunteer to help the woman acquire the precious egg. You climb down the cliff face and are nearly blown off by the harsh winds, but manage to snatch the egg and make off with it before the mother Roc returns. The woman and her daughter praise your name. [D1/S1/Stealth and Stealing]</p>
<p><b>Scholarship:</b> You nod as the woman explains her daughter's condition, but when she is done you tell her there is an alternative to stealing the egg of the legendary giant bird. "Your daughter has a disease," you inform her, "Not a curse. If you'll but help me gather a few herbs, I can make a poultice that will cure her just as well as a dose of magic egg yolk. I promise." And true to your word, the woman's daughter makes a full recovery! [D2/S1/<em>Robe of Honor</em>]</p>`,
	},
	2073: {
		index: 2073,
		text: `<p>Having stowed away on board a merchant vessel, you hear the sound of the captain's feet as he makes his way from cabin to cabin.</p>
<p><b>No Skill:</b> You remain where you are, ducked inside an empty wine barrel, in the hopes of evading discovery. The ship is too small to hide forever, however. Eventually the captain finds you, strips you of your belongings and forces you to serve as his cabin boy. [D2/S1/W-5 (Min: Beggar)/<em>Enslaved</em>]</p>
<p><b>Acting and Disguise:</b> Realizing that there is really nowhere to hide on board a ship at sea, you decide to take a different approach. You disguise yourself as an unwashed deck hand. Although the captain doesn't recognize you, he sees nothing to take from you and thus keeps you on board as a crewman until the ship arrives at port. [D1/S1/Seamanship]</p>`,
	},
	2074: {
		index: 2074,
		text: `<p>While walking along the docks one day, you spy a familiar ship sitting in the harbor: It belongs to Captain Hussein, a corsair you once set up to take the fall for a robbery you committed! As you look on, you see the captain himself disembark from the ship! You turn heel and run back to the room you've been renting, intent on packing your things and leaving town at once.</p>
<p><b>No Skill:</b> Hussein's men are waiting for you when you arrive, and they rob you and beat you within an inch of your life. Looks like the innkeeper sold you out! [D2/S1/W=Beggar/<em>Wounded</em>]</p>
<p><b>Luck:</b> You arrive just in time to witness Hussein's men dragging some other poor soul from the inn. This fortuitous case of mistaken identity provides you the time you need to make good your escape! [D1/S1/Stealth and Stealing]</p>`,
	},
	2075: {
		index: 2075,
		text: `<p>You beat the captain fair and square, there's no doubt about it, but that doesn't stop him from trying to get back the money that you won from him! You know from the moment you leave the tavern that the captain's men are following you.</p>
<p><b>No Skill:</b> Having prepared your escape route ahead of time, you lead his men on a wild goose chase all over town, eventually walking them into a blind alley that ends at a dirt-covered wall. The day, like the money, is yours! [D1/S1/W+1 (Max: Rich)]</p>
<p><b>Quick Thinking:</b> You know the town like the back of your hand, and are thus able to lead the captain's men right into a patrol of guards, who promptly give them a sound thrashing. [D1/S1/W+1 (Max: Rich)/Luck]</p>`,
	},
	2076: {
		index: 2076,
		text: `<p>The captain beat you soundly at dice, taking all of your money in the process, but you are convinced that he cheated in order to do it.</p>
<p><b>No Skill:</b> You try to follow the captain away from the tavern, in the hopes of catching him alone and getting your money back, but he spots you along the way and sends three of his men to teach you a lesson. [S1/W=Beggar/<em>Wounded</em>]</p>
<p><b>Stealth and Stealing:</b> Once out of the vicinity, you take up position across from the tavern and wait for the captain to stagger out. You follow along the rooftops, shadowing his progress on the street. Before he reaches his ship, he stops to relieve himself against a wall, and that's when you strike, taking all your money back—and then some! [D1/S2/W+1 (Max: Rich)]</p>`,
	},
	2077: {
		index: 2077,
		text: `<p>The captain's men spread out, splitting into teams of two in their search for the gold.</p>
<p><b>No Skill:</b> You pick a pair at random and follow them to their destination, but it turns out to be nothing more than a dead end. Whoever has the gold, it isn't you. [S1]</p>
<p><b>Bargaining and Evaluation:</b> You catch sight of a scroll of parchment in the captain's hand... a map! From the way his men are searching, you can discern the most likely site of the gold, and using a little brain power, you reach it before the captain! [D1/W+2 (Max: Rich)]</p>`,
	},
	2078: {
		index: 2078,
		text: `<p>Having watched this so-called captain fleece family after family out of their lives' earnings, you decide that someone must put a stop to it. And that "someone" is you.</p>
<p><b>No Skill:</b> You wait until dark before trying to sneak into the captain's stateroom, but you are caught, robbed, and thrown overboard. Still, news of your deeds reaches the captain's victims and they exalt your name loudly in the streets. [D2/S1/W-1 (Min: Penniless)/<em>Beloved</em>]</p>
<p><b>Weapon Use:</b> You wait for the perfect moment to strike, and when you do, the captain reveals himself for the coward he is. You best him with a blade and take back all the money he stole, becoming a folk hero in the process! [D2/S1/W+2 (Max: Rich)/<em>Beloved</em>]</p>`,
	},
	2079: {
		index: 2079,
		text: `<p>The captain pulls you aside and whispers, "If you steal from the other passengers, I'll make sure someone else takes the blame. Then we split the profits down the middle."</p>
<p><b>No Skill:</b> You're torn. On the one hand it certainly sounds like a good deal (assuming the captain doesn't betray you), and you're afraid of what might happen if you refuse. On the other hand, you have no desire to steal from other poor passengers. You pray to Allah for guidance, and within moments you feel certain that you must refuse. [D2/S1/Piety]</p>
<p><b>Beguiling:</b> You silently pray for guidance and Allah grants you a most subtle idea. You agree to the captain's offer, but once you've stolen the valuables, you plant them in the captain's stateroom. Upon their discovery, the passengers mutiny and the captain is thrown overboard, leaving the ship to the far more honorable first mate. [D1/S1/Stealth and Stealing]</p>`,
	},
	2080: {
		index: 2080,
		text: `<p>An hour into the trip the captain decides to charge his passengers half again as much as initially agreed upon. You loudly beseech the captain, in the name of Allah the Merciful, to reconsider and not to overcharge those who are already in need.</p>
<p><b>No Skill:</b> He refuses, then retires to his stateroom while you kneel down to pray for Allah to show him the error of his ways. An hour later the passengers mutiny and throw the captain overboard. Allah has spoken! [D2]</p>
<p><b>Scholarship:</b> Shamed by your display, the captain launches into an explanation, citing phony excuses about rising costs. When he is done you systematically dismantle every one of his arguments, countering every false fact with a true one. By the time you're through the captain has little choice but to abandon the surcharge demand, and you are celebrated as a hero among the passengers. [D2/S2/Bargaining and Evaluation/<em>Beloved</em>]</p>`,
	},
	2081: {
		index: 2081,
		text: `<p>While praying at the mosque you overhear a ship's captain discussing his plans to rob one of his wealthy passengers, throw the man overboard and report his death as an accident.</p>
<p><b>No Skill:</b> You pray to Allah for guidance, but no message of clarity arrives to guide your hand. You take the matter before the local authorities, but they tell you that your word regarding another's intent to commit a crime is not in itself proof of guilt. [S1]</p>
<p><b>Seamanship:</b> Seeing the hand of Fate in these events, you take it upon yourself to gain passage on the captain's ship by posing as a crew member. Once on board you thwart the captain's plan to rob the wealthy passenger, and in return the passenger gives you his eternal thanks... and a substantial reward! [D2/S1/W+2 (Max: Rich)]</p>`,
	},
	2082: {
		index: 2082,
		text: `<p>While sailing on board a ship one of the passengers relates to you his suspicion that the captain intends to over-crowd the passenger cabins in order to maximize profits. Concerned about the dangers posed by packing people together like sticks in a bundle, you ask the captain directly if the rumors are true.</p>
<p><b>No Skill:</b> He denies them, but you aren't so sure. Whatever he may have intended, he keeps his word and takes on no new passengers. [D1]</p>
<p><b>Bargaining and Evaluation:</b> When he confirms that they are, you decide to play mediator between the passengers and the captain. Eventually, you talk him into agreeing not to take on any new passengers in exchange for a bit of compensation, which you pay gladly, and the other passengers honor your efforts on their behalf. [D1/S1/W-1 (Min: Poor)/<em>Respected</em>]</p>`,
	},
	2083: {
		index: 2083,
		text: `<p>You are dragged from sleep in the middle of the night and brought before the captain. He demands that you tell him where to find the gold. Not having the slightest idea what the man is talking about, you simply ask him. "Don't play dumb!" he roars, and orders his men to dangle you off the side of the boat.</p>
<p><b>No Skill:</b> He asks again about the gold. "I don't know," you reply, and the captain responds by giving the signal for his men to drop you in the water. [D1/S1/Go to paragraph 315]</p>
<p><b>Storytelling:</b> You realize that protesting your ignorance or innocence is probably futile. Instead, you spin an elaborate tale about stolen gold, hidden where no one would ever find it. You offer to take the captain to it, but in truth you lead him right into a swindle and rob him blind! [D1/S2/W+2 (Max: Rich)]</p>`,
	},
	2084: {
		index: 2084,
		text: `<p>It took an hour of waiting just to gain audience with the captain, and you had to pay for the privilege, but finally you are sitting face to face with the man. "Where is the Golden Cup of the Twice-Blind Caliph?" you ask. "I must have it!" The captain slowly unwraps his turban, and there it is—the Golden Cup—resting upon his very head the whole time!</p>
<p><b>No Skill:</b> It costs you everything you have, but the Cup is yours at last! [D2/S1/W-5 (Min: Beggar)/Magic]</p>
<p><b>Weapon Use:</b> "You do not have enough gold to buy this," he says. "But... if you best me in a duel, I will simply give it to you. Free of charge." You fight with inspiration, and emerge victorious, but when the captain hands you the cup his masculine features shimmer and flow into those of the opposite sex... as do yours! [D1/S2/Magic/<em>Sex-Changed</em>]</p>`,
	},
	2085: {
		index: 2085,
		text: `<p>You are interested in setting to sea. The talk in town is that the other was once the most skilled captain in all the seas of the world. However, on his last voyage, far beyond the Spice Isles, he lost his course and lost his entire crew, returning alone a full five years after he left, terrified of the sea. You shake your head at his loss and go to find another captain. [S1]</p>`,
	},
	2086: {
		index: 2086,
		text: `<p>It is said that the captain Tariq has heard a prophecy that one of your name will be his doom, and he has set his men to finding you. They spread out, splitting into teams of two in their search for you. The net is tightening fast and time is running out!</p>
<p><b>No Skill:</b> You pick out what looks to be the weakest pair of men and wait for the right moment. Getting the drop on them, you knock them both out and make good your escape. [D1/S1]</p>
<p><b>Bargaining and Evaluation:</b> With no time to spare, you tear off a scrap of your clothing and leave it on an outstretched branch. Then you retrace your steps backwards and head off in another direction. As you hoped, the captain's men pass right by! [D1/S2/Quick Thinking]</p>`,
	},
	2087: {
		index: 2087,
		text: `<p>The other, it is said, is a great captain, but when you observe him, he is a bundle of superstitions and terrors. He double- and triple-checks ropes, taps every barrel with a hammer, and is in all ways a very portrait of uncertainty and upset. Perhaps you should find another ship to sail on?</p>
<p><b>No Skill:</b> When the other notices you moving on, he laughs a nervous, bitter laugh and calls out to you. "The sea claims its costs from all who venture on it. I pay by my caution. You cannot fail to pay just by choosing another ship!" [<em>Accursed</em>]</p>
<p><b>Bargaining and Evaluation:</b> The other might be superstitious, but you can see that there is much sense in the things he does. You carefully note his practices and encourage those on your ship to take heed. [D1/Seamanship]</p>`,
	},
	2088: {
		index: 2088,
		text: `<p>Captain Tariq has recently arrived in this town, and the word in every ear is that he has been seized by madness. He sleeps outside in the day, is awake at night and never outdoors, and he falls to the ground barking like a dog. You determine to investigate this and take every opportunity to follow him.</p>
<p><b>No Skill:</b> The poor man does indeed seem to be completely around the bend. A few days later, his ship sails off and you do not hear of him again. [S1]</p>
<p><b>Wisdom:</b> You realize that Tariq is feigning madness—his barks are actually a code to his crew, who are hurrying around the town gathering contraband to smuggle onto the ship while all eyes on their "mad" captain. You reveal the plot to the emir and are rewarded for your keen insight. [D1/S1/W+1 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	2089: {
		index: 2089,
		text: `<p>"Come with me... if you dare!" cries the captain. Holding his blade clenched between his teeth, he grabs a dangling rope and swings acrobatically to the neighboring boat. As you watch, he lands gracefully, brandishes his blade and leaps howling into the fray!</p>
<p><b>No Skill:</b> This sort of thing is really not your specialty. You are, however, more than happy to help from just where you are. You grab a bow and lay down fire for the fearless captain and his motley band of corsairs. [D1/S1/Weapon Use]</p>
<p><b>Seamanship:</b> "Allah," you shout, grasping the rope in both hands, "In my time of need, lend me your strength and courage... and if it's not too much trouble, your mercy!" You swing valiantly over the water and crash onto the other ship, drawing your blade at once and fighting at your captain's side until the day is won. [D2/S1/Luck]</p>`,
	},
	2090: {
		index: 2090,
		text: `<p>An old friend stumbles into your tent, panting and holding his sides with both hands. "You must hurry," he says at last, "The captain's on his way to kidnap your sister!" Immediately you both race after the villain.</p>
<p><b>No Skill:</b> With the head start he had on you, the captain reaches her before you arrive. It costs you most everything you have to buy her back, but you pay the ransom gladly. You'll have justice soon enough! [S1/W-2 (Min: Penniless)]</p>
<p><b>Wilderness Lore:</b> You quickly realize the captain is sticking to the coast road. Fortunately for you, you know a short cut! You arrive with moments to spare, spiriting your sister away on the back of your horse and leaving nothing but a note on the door for the captain to find: "Better luck next time, captain!" [D1/S1/Wisdom]</p>`,
	},
	2091: {
		index: 2091,
		text: `<p>The crew of sea-dogs parts before the confident stride of its captain, who emerges from among his men to face you. He says nothing, but when he sees you he stares at you with a look of horror.</p>
<p><b>No Skill:</b> Unsure as to how best to honor the captain, you decide to offer a deep bow, with a great flourish of the arm for added effect. While you are bowed down, the captain responds by slashing out at your arm and fleeing with a deafening screech. [S1/Wisdom/<em>Wounded</em>]</p>
<p><b>Scholarship:</b> You recognize this particular crew of criminals from your studies, and seem to recall that their lot reacts favorably to protracted displays of groveling. One protracted display of groveling later, the captain is mollified and you are sent on your way with a purse full of gold to show for your timely humility. [S1/W+1 (Max: Poor)/Acting and Disguise]</p>`,
	},
	2092: {
		index: 2092,
		text: `<p>You are dragged before the captain and asked to sit. He glances about constantly, as if being followed. "Life is a riddle," he says with a desperate menace. "There is one riddle in particular which haunts my every hour: What walks on four legs in the morning," the captain asks, "On two legs at noon and three legs at night?"</p>
<p><b>No Skill:</b> Your eyes light up with giddy recollection. "A man!" you cry. "The answer is 'a man!'" The captain gasps with certainty at your wisdom. [D1/S1]</p>
<p><b>Storytelling:</b> You know this one from the ancient stories of the Greeks and tell the captain calmly, "A man." Then you further explain the full story of the ancient king Oedipus and how he defeated the riddling Sphinx. The fear and madness visibly flee from him as he listens, and when you are done, he is barely the same man. He showers you with gifts for your wisdom. [D1/S1/W+2 (Max: Rich)]</p>`,
	},
	2093: {
		index: 2093,
		text: `<p>You have been found out! You were taking liberties with the captain's oldest child, and the captain finally found out about it. Both you and your paramour are summoned to his presence. "I have many enemies who will take advantage of any dishonor on my reputation. I will not stand by as my family honor is besmirched," the captain spits.</p>
<p><b>No Skill:</b> "You must either leave at once, never to return, or fight me for the wrong you have done my family." Wanting only to honor the man, you agree to take your leave. When you return home, however, you find the captain's eldest waiting there for you. He ran away just to be with you, and verily is his father right wroth! [D2/S1/<em>Pursued</em>]</p>
<p><b>Bargaining and Evaluation:</b> You apologize profusely, and before he can respond, you offer to make it right. "How?" he demands to know. "Simple," you reply. "I shall make an honest couple of us." He is still upset, but one look into his child's hopeful eyes melts his cold heart, and he consents. [D2/S1/<em>Married</em>]</p>`,
	},
	2094: {
		index: 2094,
		text: `<p>The beach is approaching too fast and you question the wisdom of the captain. The captain does not respond and you see the blank look of his eyes as they stare unblinkingly toward the approaching island.</p>
<p><b>No Skill:</b> You yell for everyone to brace themselves—just as a reef tears the hull open like a cracked nut. [D1/Have an immediate encounter on Ape Island (Matrix N)]</p>
<p><b>Seamanship:</b> You push the captain aside and turn the wheel hard to starboard. This action saves the ship and the lives of the crew. All hail you as their new captain and you bring everyone safely home. [D2/<em>Respected</em>]</p>`,
	},
	2095: {
		index: 2095,
		text: `<p>After months of searching you finally pin down the mad captain's location. When you find him, he is drinking alone in the back of a dingy tavern.</p>
<p><b>No Skill:</b> "I heard it was the Six-Pointed Star of Wonder that drove you mad," you whisper, leaning in. "Is that true?" The captain's lip quivers and his brow furrows. "You'll not speak of such things in my presence!" he spits. "Do you hear me? Never!" [S1]</p>
<p><b>Beguiling:</b> Under the pretext of looking for a good sailor to help navigate an especially treacherous stretch of seaway, you engage the mad captain in conversation. After a few mugs of wine you steer the conversation in the direction of antiquities, and from there to talk of the infamous Six-Pointed Star of Wonder. Although the captain refuses to take part in any expedition involving the recovery thereof, he does agree to sell you an old map, but he implores you not to make use of it! [D1/S1/W-1 (Min: Penniless)/<em>Determined</em>]</p>`,
	},
	2096: {
		index: 2096,
		text: `<p>While riding your horse by the shore one night, you smell smoke on the wind and see a dim orange glow on the horizon. Riding on, you soon realize that the source of the glow is a boat anchored just past the breakers. It's engulfed in flames! Then a figure appears on the beach. "What happened?" you ask. "Mutiny!" he croaks, coughing up sea water.</p>
<p><b>No Skill:</b> [S1]</p>
<p><b>Bargaining and Evaluation:</b> You notice that a jetty juts out to very near where the ship is moored, and you ride your horse down to the end of it. Pulling a length of rope off your saddle bags, you fashion a lifeline and help pull the survivors up from the water to safety. The captain calls you "an angel of Allah's mercy" and praises you. [D1/S1/<em>Blessed</em>]</p>`,
	},
	2097: {
		index: 2097,
		text: `<p>The Six-Pointed Star of Wonder is a jewel which is rumored to drive its owner mad. You disbelieve the legend until one day you find a rough sea-captain wearing the very Star—and wearing also the clear signs of madness. Because of his affliction, he is an easy mark and you make off with the gem from under his very eyes.</p>
<p><b>No Skill:</b> Although all the signs were there in front of you, you somehow thought that you would escape the curse of the Star. Sadly, no. The taint remains even after you have resold the gem. [S1/W+1 (Max: Rich)/<em>Insane</em>]</p>
<p><b>Scholarship:</b> The selfsame stories which lead you to seek the gem also told you of the proper rituals, prayers, and deeds to remove the curse. Not only do you avoid madness, you free all those who have suffered the curse from bearing the gem; they sing your praises. [D1/W+2 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	2098: {
		index: 2098,
		text: `<p>After years of searching for the Six-Pointed Star of Wonder, you finally track its location to the mad captain who, according to legend, first recovered it from its dusty resting place.</p>
<p><b>No Skill:</b> Under the pretext of looking for a good sailor to help navigate an especially treacherous stretch of seaway, you engage the mad captain in conversation. You continue to ply him with wine until, finally, he passes out under the table, leaving you free to sneak into his quarters and pilfer the artifact for yourself. Unfortunately, the rumors about the Star being cursed are true, thus making you now the curse's bearer! [S1/<em>Accursed</em>]</p>
<p><b>Wisdom:</b> Under the pretext of looking for a good sailor to help navigate an especially treacherous stretch of seaway, you engage the mad captain in conversation. Over the course of the evening, it becomes clear to you that the captain was just as sane before acquiring the relic as he is insane now. "It's cursed," he mewls. "No good can come of it." And although you've spent years in search of it, and are finally at the threshold of acquiring it, something in the mad captain's words rings true. With a clear conscience you feel you can finally abandon your need to acquire the Star. [D2/S1/Bargaining and Evaluation]</p>`,
	},
	2099: {
		index: 2099,
		text: `<p>While traveling along an open road, you espy an old man, dressed in captain garbs, digging on the side of the road. Lying next to him are two fat purses. As you stare, he catches sight of you. "Don't ye be thinking of stealing my treasure!"</p>
<p><b>No Skill:</b> You are too shocked to respond and quickly hurry away. [S1]</p>
<p><b>Stealth and Stealing, Quick Thinking:</b> You tell him you wouldn't dream of it—that you were just making note of the place in which it was buried that you might make a map for him. The captain is grateful for your aid. When he is done, he takes your hastily drawn map and departs. You wait patiently then dig up the treasure for yourself. [D1/S2/W+2 (Max: Rich)]</p>`,
	},
};
